BEGIN;

CREATE TABLE rh.tipo_falta (id_tipo_falta int4 NOT NULL, descricao varchar(255), servidor bool, professor bool, CONSTRAINT tipo_falta_pkey PRIMARY KEY (id_tipo_falta));

ALTER TABLE rh.tipo_falta OWNER TO sigeduc;

GRANT ALL ON
TABLE rh.tipo_falta TO sigeduc;

CREATE SEQUENCE rh.tipo_falta_seq INCREMENT BY 1
START WITH 3 MINVALUE 1 NO MAXVALUE CACHE 1;

ALTER SEQUENCE rh.tipo_falta_seq OWNER TO sigeduc;

GRANT ALL ON
SEQUENCE rh.tipo_falta_seq TO sigeduc;

INSERT INTO rh.tipo_falta (id_tipo_falta, descricao, servidor, professor)
VALUES (1, 'Falta Abonada', TRUE, TRUE);

INSERT INTO rh.tipo_falta (id_tipo_falta, descricao, servidor, professor)
VALUES (2, 'Falta Não Abonada', TRUE, TRUE);

INSERT INTO rh.tipo_falta (id_tipo_falta, descricao, servidor, professor)
VALUES (3, 'Falta Aula Atividade', FALSE, TRUE);

ALTER TABLE pessoas.falta_servidor ADD id_tipo_falta int4;

ALTER TABLE pessoas.falta_servidor ADD CONSTRAINT falta_servidor_id_tipo_falta_fkey FOREIGN KEY (id_tipo_falta) REFERENCES rh.tipo_falta(id_tipo_falta);

CREATE TABLE rh.status_falta (id_status_falta int4 NOT NULL, descricao varchar(255), CONSTRAINT status_falta_pkey PRIMARY KEY (id_status_falta));

ALTER TABLE rh.status_falta OWNER TO sigeduc;

GRANT ALL ON
TABLE rh.status_falta TO sigeduc;

INSERT INTO rh.status_falta (id_status_falta, descricao)
VALUES (1, 'Pendente');

INSERT INTO rh.status_falta (id_status_falta, descricao)
VALUES (2, 'Aprovada');

INSERT INTO rh.status_falta (id_status_falta, descricao)
VALUES (3, 'Recusada');

CREATE SEQUENCE rh.status_falta_seq INCREMENT BY 1
START WITH 3 MINVALUE 1 NO MAXVALUE CACHE 1;

ALTER SEQUENCE rh.status_falta_seq OWNER TO sigeduc;

GRANT ALL ON
SEQUENCE rh.status_falta_seq TO sigeduc;

ALTER TABLE pessoas.falta_servidor ADD id_status_falta int4;

ALTER TABLE pessoas.falta_servidor ADD quantidade_dias int4;

ALTER TABLE pessoas.falta_servidor ADD CONSTRAINT falta_servidor_id_status_falta_fkey FOREIGN KEY (id_status_falta) REFERENCES rh.status_falta(id_status_falta);

ROLLBACK;

SELECT *
FROM basico.turma_serie ts
WHERE ts.id_turma_serie IN (52644456, 52809652, 53065032, 53211768);

SELECT DISTINCT p.nome, u.login, t.id_turma_serie
FROM comum.usuario u
JOIN comum.pessoa p ON
p.id_pessoa = u.id_pessoa
JOIN rh.servidor s ON
s.id_pessoa = p.id_pessoa
JOIN ensino.docente_turma dt ON
dt.id_docente = s.id_servidor
JOIN ensino.turma t ON
t.id_turma = dt.id_turma
WHERE dt.ativo
AND u.login ILIKE '%aldeisiasilva@gmail.com%';
AND ano;

SELECT *
FROM rh.servidor s ;

