-- DOCUMENTAÇÃO DA CONSULTA SQL
-- Tabela principal: rh.servidor
-- Coluna analisada: servidor7_.quantidadefaltaspendentes
-- Objetivo: Retornar TRUE se houver faltas pendentes (> 0), senão FALSE.
-- ====================================================================;SELECT 1
FROM rh.servidor ;

SELECT EXISTS (
        SELECT 1
FROM rh.servidor servidor7_
WHERE servidor7_.quantidadefaltaspendentes IS NOT NULL
AND servidor7_.quantidadefaltaspendentes > 0
    ) AS cliente_tem_faltas_pendentes;

